 "content": "from math import gcd

def transform(grid):
    out = [row[:] for row in grid]
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    for (r1, c1), (r2, c2) in zip(ones, ones[1:]):
        steps = gcd(abs(r2-r1), abs(c2-c1))
        if steps == 0:
            continue
        dr, dc = (r2-r1)//steps, (c2-c1)//steps
        for i in range(1, steps):
            r, c = r1+i*dr, c1+i*dc
            if out[r][c] == 4:
                out[r][c] = 1
    return out
